const fs=require("node:fs"),{JSDOM}=require("jsdom"),{createRequire}=require("node:module");
const dom=new JSDOM("<div id='app'></div>",{pretendToBeVisual:true,url:"http://localhost/"});
const win=dom.window;
for(const key of ["window","document","Element","HTMLElement","Node","Text","Document","MutationObserver"])global[key]=win[key];
global.self=win;
global.requestAnimationFrame=win.requestAnimationFrame.bind(win);
global.cancelAnimationFrame=win.cancelAnimationFrame.bind(win);
const gl=require("@glimmerx/core");
const coreRequire=createRequire(require.resolve("@glimmer/core"));
const compiler=coreRequire("@glimmer/compiler");
const runtime=coreRequire("@glimmer/runtime");
const opcode=coreRequire("@glimmer/opcode-compiler");
const fsSrc=fs.readFileSync(process.argv[2],"utf8");
const content=new (require("content-tag").Preprocessor)().process(fsSrc,{filename:process.argv[2]}).code;
const host=require("esbuild").transformSync(content,{loader:"ts",format:"cjs"}).code;
const template=(markup,options)=>{
 const lexicalScope = name => {
   try { options.eval(name); return true; } catch(error) { if(error instanceof ReferenceError)return false; throw error; }
 };
 const [block,used]=compiler.precompileJSON(markup,{strictMode:true,lexicalScope});
 const t=opcode.templateFactory({block:JSON.stringify(block),id:"corpus-original",moduleName:process.argv[2],isStrictMode:true,
     scope:()=>used.map(name=>options.eval(name))});
 const component=runtime.templateOnlyComponent(process.argv[2],"Greeting");
 gl.setComponentTemplate(t,component);
 return component;
};
const result={exports:{}};
new Function("module","exports","require",host)(result,result.exports,name=>{
 if(name==="@ember/template-compiler")return {template};
 return require(name);
});
(async()=>{
 await gl.renderComponent(result.exports.default,document.querySelector("#app"));
 const h=document.querySelector("#app h1");
 if(h?.textContent!=="Hello, World!")throw Error(document.body.innerHTML);
 console.log(h.textContent);
 dom.window.close();
})().catch(e=>{console.error(e);process.exitCode=1;});
